(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*12+Math.cos(y*0.02-t*0.15)*8;
  const w1y = Math.cos(y*0.015-t*0.25)*12+Math.sin(x*0.018+t*0.3)*8;
  const w2x = Math.sin(x*0.035-t*0.4)*5+Math.cos(y*0.03+t*0.35)*4;
  const w2y = Math.cos(y*0.03+t*0.45)*5+Math.sin(x*0.025-t*0.3)*4;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.6+1)*40,0.11,2.1,0.85],
    [400+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.8)*50,0.085,1.8,1.05]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,w]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;cS+=Math.sin(d*f*1.3-t*sp*0.8+3)*w;}
  const n=src.length,act=aS/n,inh=iS/n,cat=cS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.06+sy*0.08-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2+t*2)*0.3;
  const cells=[[120,60],[240,120],[360,60],[60,180],[180,200],[300,180],[420,200],[240,240]];
  let minD=999,secD=999;
  for(const[cX,cY]of cells){const xd=cX+Math.sin(t*0.3+cX*0.01)*15,yd=cY+Math.cos(t*0.25+cY*0.01)*15,d=Math.sqrt((sx-xd)**2+(sy-yd)**2);if(d<minD){secD=minD;minD=d;}else if(d<secD)secD=d;}
  const voronoi=Math.sin((secD-minD)*0.15)*0.5;
  const r1=act-inh*0.7+bg*0.25+spiral*0.3+voronoi*0.2;
  const r2=cat*0.5-act*0.3+spiral*0.2+voronoi*0.15;
  const reaction=Math.tanh(r1*2)*(0.85+Math.tanh(r2)*0.15);
  const membrane=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const edge=Math.abs(reaction)>0.65?1+(Math.abs(reaction)-0.65)*0.8:1;
  const shimmer=1+Math.sin(dist*0.1-t*3)*0.03;
  const blend=reaction*0.7+membrane*0.3,v=blend*0.5+0.5;
  const pal=[[4,12,48],[8,35,82],[12,72,110],[18,120,130],[30,165,140],[140,200,120],[220,210,80],[240,160,60],[220,100,55],[180,55,75],[120,30,80],[60,20,75],[20,15,65],[4,12,48]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=(0.85+Math.sin(reaction*Math.PI)*0.15)*shimmer;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0];
}
